import numpy as np, json

def transform(grid):
    g=np.array(grid); H,W=g.shape
    vals,counts=np.unique(g,return_counts=True)
    bg=vals[np.argmax(counts)]
    seen=np.zeros_like(g,bool); comps=[]
    for i in range(H):
        for j in range(W):
            if seen[i,j] or g[i,j]==bg: continue
            col=g[i,j]; st=[(i,j)]; seen[i,j]=1; cells=set()
            while st:
                r,c=st.pop(); cells.add((r,c))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr,nc] and g[nr,nc]==col:
                            seen[nr,nc]=1; st.append((nr,nc))
            comps.append((int(col),cells))
    def key(cells):
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        r0,c0=min(rs),min(cs)
        return tuple(sorted((r-r0,c-c0) for r,c in cells))
    groups=defaultdict(list)
    for col,cells in comps: groups[key(cells)].append((col,cells))
    # largest duplicate group (>=2 members, tie-break by size)
    best=None
    for k,v in groups.items():
        if len(v)>=2:
            sz=len(v[0][1])
            if best is None or sz>best[0]: best=(sz,k,v)
    out=[row[:] for row in grid]
    if best is None: return out
    _,k,v=best
    # rightmost member: max min-col
    v2=sorted(v, key=lambda t: min(c for r,c in t[1]))
    target_cells=v2[-1][1]
    # target color: color with exactly one component, excluding colors in dup group, largest shape
    cnt=Counter(col for col,_ in comps)
    dupcolors={col for col,_ in v}
    cands=[(max(len(c) for cc,c in comps if cc==col), col) for col in cnt if cnt[col]==1 and col not in dupcolors]
    if not cands: return out
    tgt=max(cands)[1]
    for r,c in target_cells: out[r][c]=tgt
    return out

