def comps_of(g):
    g=np.array(g); H,W=g.shape
    vals,counts=np.unique(g,return_counts=True); bg=vals[np.argmax(counts)]
    seen=np.zeros_like(g,bool); out=[]
    for i in range(H):
        for j in range(W):
            if seen[i,j] or g[i,j]==bg: continue
            col=int(g[i,j]); st=[(i,j)]; seen[i,j]=1; cells=set()
            while st:
                r,c=st.pop(); cells.add((r,c))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr,nc] and g[nr,nc]==col:
                            seen[nr,nc]=1; st.append((nr,nc))
            out.append({'col':col,'cells':cells})
    return out,bg

def variants(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    pts=[(r-min(rs),c-min(cs)) for r,c in cells]
    res=set()
    cur=pts
    for _ in range(4):
        res.add(tuple(sorted(cur)))
        res.add(tuple(sorted((r,c) for r,c in [(p[0],-p[1]) for p in cur])))
        cur=[(c,-r) for r,c in cur]
    return res

def norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))

